import json
from fractions import Fraction

result = Fraction(144, 12)

if result.denominator == 1:
    answer = str(result.numerator)
    check = result * 12 == 144
    print(json.dumps({
        "final_answer": answer,
        "evidence": {
            "numerator": 144,
            "denominator": 12,
            "quotient": answer,
            "verified_by_multiplication": check
        }
    }))
else:
    print("UNSUPPORTED")
